import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"虚拟机逃逸","description":"","frontmatter":{"title":"虚拟机逃逸","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vm-escape.md","filePath":"cs/vm-escape.md","lastUpdated":1789023840000}'),c={name:"cs/vm-escape.md"};function E(B,a,m,_,A,u){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="虚拟机逃逸" tabindex="-1">虚拟机逃逸 <a class="header-anchor" href="#虚拟机逃逸" aria-label="Permalink to &quot;虚拟机逃逸&quot;">​</a></h1><div class="epigraph"><p>虚拟机把客当做不可信，但设备模拟、共享内存与管理接口是 TCB。逃逸指客中代码到达宿主机。防御是缩小模拟面、设备 IOMMU、及时补丁，而不是假设「有虚拟化即隔离」。</p><footer>—— 据 Barham et al., Xen, SOSP 2003 的隔离目标；对照 Anderson；CVE 史仅作动机点名</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/flush-reload">Flush+Reload</a>还在共驻泄漏。缺口是<strong>完整性边界</strong>：客到宿。本课讲 TCB 面，不给逃逸 PoC。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>QEMU 设备、virtio、管理 API。洞在模拟代码等于洞在宿。缺口是：最小设备、快照补丁、嵌套关闭。</p><h3 id="机密计算" tabindex="-1">机密计算 <a class="header-anchor" href="#机密计算" aria-label="Permalink to &quot;机密计算&quot;">​</a></h3><p>对运营商隔离不自动防客逃到另一客，除非另有策略。</p><p><span class="marginnote">Xen/KVM 文献。禁止逃逸教程。容器下一课是更薄的边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 IaaS 威胁模型。补丁窗口。下一课容器逃逸。</p>',12)),(e(),n(p,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GUEST%5B%22%E5%AE%A2%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%E6%A8%A1%E6%8B%9F%20TCB%22%5D%0A%20%20DEV%20--%3E%20HOST%5B%22%E5%AE%BF%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20MIN%5B%22%E7%BC%A9%E5%B0%8F%E6%A8%A1%E6%8B%9F%E9%9D%A2%22%5D%20--%3E%20HARD%5B%22%E6%8F%90%E9%AB%98%E9%80%83%E9%80%B8%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>隔离强度等于 TCB 正确性。容器共用内核，边界更薄。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零 PoC。容器逃逸下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>侧信道漏 C；逃逸破隔离完整。</li><li>设备模拟是高危 TCB。</li><li>虚拟化不是自动证明。</li><li>下一课容器逃逸。</li><li>出处：Barham et al., Xen, 2003；Anderson。</li></ul>',8))])}const P=l(c,[["render",E]]);export{T as __pageData,P as default};
